#!/usr/bin/env bash
# Emit, on stdout, the SQL stream that (re)loads poblacion_radio from the 2022 census population CSV.
# Pipe it into the stack's psql: `make importar-poblacion` (add ENV_FILE=.env.local for the local stack).
#
# Input: go_algorithms_worker/data/poblacion-radios.csv, columns `codigo_radio,habitantes,hogares`
# (generated by `make mapa-datos`). Codes lose their leading zero in some exports, so they are
# left-padded to 9 digits. Rows without habitantes are skipped.
#
# Idempotent: one transaction stages the CSV, truncates poblacion_radio and reloads it, so every run
# leaves identical contents (no duplicates, no orphans). A duplicate code aborts the whole run.
# Needs V011 applied first (`make migrate`). Takes no input but the fixed CSV path.
set -euo pipefail

DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CSV="${POBLACION_CSV:-$DIR/../../go_algorithms_worker/data/poblacion-radios.csv}"

[ -f "$CSV" ] || { echo "population CSV not found: $CSV (run make mapa-datos)" >&2; exit 1; }

cat <<'SQL'
BEGIN;
CREATE TEMP TABLE poblacion_staging (codigo_radio text, habitantes integer, hogares integer) ON COMMIT DROP;
COPY poblacion_staging FROM STDIN WITH (FORMAT csv, HEADER true);
SQL
cat "$CSV"
cat <<'SQL'
\.
TRUNCATE poblacion_radio;
INSERT INTO poblacion_radio (codigo_radio, habitantes)
SELECT lpad(codigo_radio, 9, '0'), habitantes FROM poblacion_staging WHERE habitantes IS NOT NULL;
COMMIT;
SELECT count(*) AS filas_poblacion_radio, sum(habitantes) AS habitantes_total FROM poblacion_radio;
SQL
